import java.util.*;

class AutocompleteSystemBrute {
    Map<String, Integer> counts = new HashMap<>();
    StringBuilder cur = new StringBuilder();

    AutocompleteSystemBrute(String[] sentences, int[] times) {
        for (int i = 0; i < sentences.length; i++) counts.put(sentences[i], times[i]);
    }

    List<String> input(char c) {
        if (c == '#') {
            counts.merge(cur.toString(), 1, Integer::sum);
            cur.setLength(0);
            return new ArrayList<>();
        }
        cur.append(c);
        String prefix = cur.toString();
        List<Map.Entry<String, Integer>> matches = new ArrayList<>();
        for (Map.Entry<String, Integer> e : counts.entrySet()) {          // scan ALL sentences
            if (e.getKey().startsWith(prefix)) matches.add(e);
        }
        matches.sort((a, b) -> !a.getValue().equals(b.getValue()) ? b.getValue() - a.getValue() : a.getKey().compareTo(b.getKey()));
        List<String> result = new ArrayList<>();
        for (int i = 0; i < Math.min(3, matches.size()); i++) result.add(matches.get(i).getKey());
        return result;
    }
}

