#include <bits/stdc++.h>
using namespace std;

class AutocompleteSystemBrute {
public:
    unordered_map<string,int> counts;
    string cur;

    AutocompleteSystemBrute(vector<string>& sentences, vector<int>& times) {
        for (int i = 0; i < (int)sentences.size(); i++) counts[sentences[i]] = times[i];
    }

    vector<string> input(char c) {
        if (c == '#') {
            counts[cur]++;
            cur.clear();
            return {};
        }
        cur += c;
        vector<pair<string,int>> matches;
        for (auto& [s, cnt] : counts) {                                    // scan ALL sentences
            if (s.substr(0, cur.size()) == cur) matches.push_back({s, cnt});
        }
        sort(matches.begin(), matches.end(), [](auto& a, auto& b) {
            return a.second != b.second ? a.second > b.second : a.first < b.first;
        });
        vector<string> result;
        for (int i = 0; i < min(3, (int)matches.size()); i++) result.push_back(matches[i].first);
        return result;
    }
};

