class TrieNode:
    def __init__(self):
        self.children = {}
        self.counts = {}                          # sentence -> count, for every sentence through this node

class AutocompleteSystem:
    def __init__(self, sentences, times):
        self.root = TrieNode()
        self.cur = ''
        self.node = self.root
        for s, t in zip(sentences, times):
            self._add(s, t)

    def _add(self, s, delta):
        node = self.root
        node.counts[s] = node.counts.get(s, 0) + delta
        for ch in s:
            node = node.children.setdefault(ch, TrieNode())
            node.counts[s] = node.counts.get(s, 0) + delta       # cache at EVERY node along the path

    def input(self, c):
        if c == '#':
            self._add(self.cur, 1)
            self.cur = ''
            self.node = self.root
            return []
        self.cur += c
        if self.node is not None:
            self.node = self.node.children.get(c)                 # advance by one character
        if self.node is None:
            return []
        matches = sorted(self.node.counts.items(), key=lambda x: (-x[1], x[0]))
        return [s for s, _ in matches[:3]]

