import java.util.*;

class TrieNode {
    Map<Character, TrieNode> children = new HashMap<>();
    Map<String, Integer> counts = new HashMap<>();    // sentence -> count, for every sentence through this node
}

class AutocompleteSystem {
    TrieNode root = new TrieNode();
    TrieNode node = root;
    StringBuilder cur = new StringBuilder();

    AutocompleteSystem(String[] sentences, int[] times) {
        for (int i = 0; i < sentences.length; i++) add(sentences[i], times[i]);
    }

    void add(String s, int delta) {
        TrieNode n = root;
        n.counts.merge(s, delta, Integer::sum);
        for (char ch : s.toCharArray()) {
            n = n.children.computeIfAbsent(ch, k -> new TrieNode());
            n.counts.merge(s, delta, Integer::sum);                 // cache at EVERY node along the path
        }
    }

    List<String> input(char c) {
        if (c == '#') {
            add(cur.toString(), 1);
            cur.setLength(0);
            node = root;
            return new ArrayList<>();
        }
        cur.append(c);
        if (node != null) node = node.children.get(c);               // advance by one character
        if (node == null) return new ArrayList<>();
        List<Map.Entry<String, Integer>> matches = new ArrayList<>(node.counts.entrySet());
        matches.sort((a, b) -> !a.getValue().equals(b.getValue()) ? b.getValue() - a.getValue() : a.getKey().compareTo(b.getKey()));
        List<String> result = new ArrayList<>();
        for (int i = 0; i < Math.min(3, matches.size()); i++) result.add(matches.get(i).getKey());
        return result;
    }
}

