#include <bits/stdc++.h>
using namespace std;

struct TrieNode {
    unordered_map<char, TrieNode*> children;
    unordered_map<string,int> counts;                 // sentence -> count, for every sentence through this node
};

class AutocompleteSystem {
public:
    TrieNode* root = new TrieNode();
    TrieNode* node = root;
    string cur;

    AutocompleteSystem(vector<string>& sentences, vector<int>& times) {
        for (int i = 0; i < (int)sentences.size(); i++) add(sentences[i], times[i]);
    }

    void add(const string& s, int delta) {
        TrieNode* n = root;
        n->counts[s] += delta;
        for (char ch : s) {
            if (!n->children.count(ch)) n->children[ch] = new TrieNode();
            n = n->children[ch];
            n->counts[s] += delta;                                    // cache at EVERY node along the path
        }
    }

    vector<string> input(char c) {
        if (c == '#') {
            add(cur, 1);
            cur.clear();
            node = root;
            return {};
        }
        cur += c;
        if (node != nullptr) {
            auto it = node->children.find(c);
            node = (it != node->children.end()) ? it->second : nullptr;   // advance by one character
        }
        if (node == nullptr) return {};
        vector<pair<string,int>> matches(node->counts.begin(), node->counts.end());
        sort(matches.begin(), matches.end(), [](auto& a, auto& b) {
            return a.second != b.second ? a.second > b.second : a.first < b.first;
        });
        vector<string> result;
        for (int i = 0; i < min(3, (int)matches.size()); i++) result.push_back(matches[i].first);
        return result;
    }
};
